import { Link, useLoaderData } from "react-router-dom";
import React from "react";
import { ExternalLink } from "../components/ExternalLink";
import classNames from "classnames";
import {
    Authenticated,
    AuthenticationData,
    isLoggedIn,
    NotAuthenticated,
} from "../Login";

// Views

function CardProdFree({
    authenticated,
}: {
    authenticated: Authenticated | NotAuthenticated;
}) {
    const [actionText, actionLink, actionIcon] = !isLoggedIn(authenticated)
        ? [
              "Get started",
              "https://sourcery.ai/signup/?product=prod_opensource&interval=year",
              "mi-arrow-right",
          ]
        : authenticated.userClaims.product === "prod_opensource"
        ? ["Currently active", null, "mi-favorite"]
        : ["Enabled", null, "mi-check"];

    return (
        <div className="basis-1/3 flex flex-col flex-grow rounded-sm overflow-clip">
            <div className="flex flex-col flex-grow bg-black-100 pt-7 px-7 pb-8">
                <div className={"min-h-[10rem]"}><p className={"font-bold font-mono"}>For open source projects</p>
                    <h2 className="font-bold text-2xl">Free</h2>
                    <p className="text-black-300 min-h-8">
                        Review open source code anytime, anywhere. With or without an account.
                    </p></div>
                <ul className="mt-8 divide-y divide-black-200">
                    <li className="py-4">Real time review in IDE for open source projects</li>
                    <li className="py-4">Fully local code analysis</li>
                </ul>
            </div>
            {actionLink ? (
                <ExternalLink
                    href={actionLink}
                    className={
                        "py-5 px-7 text-black cursor-pointer bg-black-200 font-bold hover:bg-opacity-90"
                    }
                >
                    <div className="flex flex-row gap-4 items-center">
                        <span>{actionText}</span>
                        <i className={classNames(actionIcon, "text-2xl")}></i>
                    </div>
                </ExternalLink>
            ) : (
                <div className={"py-5 px-7 text-black bg-black-200 font-bold"}>
                    <div className="flex flex-row gap-4 items-center">
                        <span>{actionText}</span>
                        <i className={classNames(actionIcon, "text-2xl")}></i>
                    </div>
                </div>
            )}
        </div>
    );
}

