export const Account = () => {
    const { authenticated } = useLoaderData() as AuthenticationData<
        Authenticated | NotAuthenticated
    >;

    return (
        <main
            className={
                "flex flex-col h-screen overflow-y-scroll font-body text-black-500 py-8 px-9"
            }
        >
            <div className="mb-7">
                <h1 className="text-3xl">Your Account</h1>

                {!isLoggedIn(authenticated) && (
                    <>
                        <p className="text-black-300 mt-7">
                            Your device isn't authenticated with Sourcery. Sign
                            in, or get started with one of the accounts below.
                        </p>
                        <div className={"mt-7 flex"}>
                            <Link
                                to={"/login"}
                                className={
                                    "font-bold bg-orange hover:bg-opacity-90 px-6 py-5 rounded-sm"
                                }
                            >
                                <div className="flex flex-row items-center">
                                    <span>Sign In</span>
                                    <i className="mi-log-in ml-5 text-xl"></i>
                                </div>
                            </Link>
                        </div>
                    </>
                )}
            </div>

            <div className="flex flex-row gap-4 border-t-[2px] border-black-100 pt-7">
                <CardProdFree authenticated={authenticated} />
                <CardProdPro authenticated={authenticated} />
                <CardProdTeam authenticated={authenticated} />
            </div>
        </main>
    );
};
