import React, {HTMLAttributes, InputHTMLAttributes} from "react";

interface TextInputProps {
    inputProps?: InputHTMLAttributes<HTMLInputElement>;
    icon?: string;
    iconProps?: HTMLAttributes<HTMLElement>;
}

export const TextInput = ({ inputProps, icon, iconProps }: TextInputProps) => (
    <div
        className={
            "group flex flex-row items-center bg-black-100 border border-transparent border-b-black-200 px-[12px] py-[12px] gap-[10px] w-[200px] mt-7 box-content " +
            "focus-within:border-orange hover:border-black-200 hover:focus-within:border-orange"
        }
    >
        <input
            type={"text"}
            placeholder={"Search for a rule..."}
            className={
                "bg-transparent flex flex-row w-full outline-none placeholder:text-black-300 text-black-500"
            }
            {...inputProps}
        />
        {icon && (
            <i
                className={`${icon} text-black-300 group-hover:text-black-500`}
                {...iconProps}
            />
        )}
    </div>
);
