import React from "react";
import {ExternalLink} from "./ExternalLink";

/**
 * A shallow wrapper around an external link providing default styles and an icon.
 */
export const HubLink = ({
    children,
    className,
    rel,
    target,
    icon,
    ...props
}: React.AnchorHTMLAttributes<HTMLAnchorElement> & { icon?: string }) => {
    return (
        <ExternalLink
            {...props}
            className={className ?? "text-orange-200 cursor-pointer hover:underline"}
            rel={rel ?? "noopener noreferrer"}
            target={target ?? "_blank"}
        >
            {children} <i className={icon ?? "mi-external-link"}></i>
        </ExternalLink>
    );
};
