/**
 * Displays getting started tips for new Sourcery users.
 */
import classNames from "classnames";
import React, { PropsWithChildren, ReactNode } from "react";
import { Link, useLoaderData, useNavigate } from "react-router-dom";
import { ExternalLink } from "../components/ExternalLink";
import { HubLink } from "../components/HubLink";
import { BigIcon } from "../components/BigIcon";
import { Authenticated, AuthenticationData, NotAuthenticated } from "../Login";

// Interfaces

interface GettingStartedItemProps extends PropsWithChildren {
    icon: string;
    title: string;
    description?: ReactNode;
    actions?: GettingStartedAction[];
}

interface GettingStartedBaseAction {
    title: string;
    icon?: string;
    primary?: boolean;
}

interface GettingStartedLinkAction extends GettingStartedBaseAction {
    link: string;
}

interface GettingStartedCallbackAction extends GettingStartedBaseAction {
    callback: () => void;
}

type GettingStartedAction =
    | GettingStartedLinkAction
    | GettingStartedCallbackAction;

// Functions

const isLinkAction = (
    action: GettingStartedAction
): action is GettingStartedLinkAction => action.hasOwnProperty("link");

// Components

const GettingStartedItem = ({
    icon,
    title,
    description,
    actions,
}: GettingStartedItemProps) => {
    return (
        <div className={"flex flex-row gap-5 border-b py-6 border-b-black-100"}>
            <div>
                <BigIcon icon={icon} />
            </div>
            <div className="flex flex-col">
                <h2 className={"font-bold mt-2"}>{title}</h2>
                <div className={"text-black-300 mt-2"}>{description}</div>
                {actions?.length && (
                    <div className={"mt-4 flex flex-row gap-4"}>
                        {actions.map((action) => (
                            <GettingStartedActionButton
                                key={action.title}
                                {...action}
                            />
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
};

const GettingStartedActionButton = (action: GettingStartedAction) => {
    return isLinkAction(action) ? (
        <ExternalLink
            href={action.link}
            className={classNames(
                "p-4 px-5 font-bold rounded-sm text-black-500 cursor-pointer",
                action.primary
                    ? "bg-orange-100 hover:bg-orange-200"
                    : "bg-transparent hover:bg-black-100 border border-black-100"
            )}
        >
            <div className="flex flex-row items-center">
                <span>{action.title}</span>
                <span className={"ml-4 text-xl"}>
                    <i className={action.icon ?? "mi-external-link"}></i>
                </span>
            </div>
        </ExternalLink>
    ) : (
        <button
            className={classNames(
                "p-4 px-5 font-bold rounded-sm text-black-500",
                action.primary
                    ? "bg-orange-100 hover:bg-orange-200"
                    : "bg-transparent hover:bg-black-100 border border-black-100"
            )}
            onClick={action.callback}
        >
            <div className="flex flex-row items-center">
                <span>{action.title}</span>
                {action.icon && (
                    <span className={"ml-4 text-xl"}>
                        <i className={action.icon}></i>
                    </span>
                )}
            </div>
        </button>
    );
};

// Views

export const GettingStarted = () => {
    const navigate = useNavigate();
    const { authenticated } = useLoaderData() as AuthenticationData<
        Authenticated | NotAuthenticated
    >;
    return (
        <div
            className={
                "flex flex-col flex-grow h-screen overflow-y-scroll font-body text-black-500 py-8 px-9"
            }
        >
            <h1 className="text-3xl mb-5">Getting started</h1>
            <p className="text-black-300 mb-5">
                Get the most out of Sourcery by working through the tasks below.
            </p>

            <div className="flex flex-col border-t-[2px] border-black-100">
                {!authenticated.isAuthenticated && (
                    <GettingStartedItem
                        icon={"mi-user"}
                        title={"Create a Sourcery account"}
                        description={
                            "Try out Sourcery Pro features for 14 days."
                        }
                        actions={[
                            {
                                title: "Create Account",
                                link: "https://sourcery.ai/signup/?product=prod_pro",
                                primary: true,
                            },
                            {
                                title: "Sign In",
                                callback: () => navigate("/login"),
                                icon: "mi-log-in",
                            },
                        ]}
                    />
                )}
                <GettingStartedItem
                    icon={"mi-eye"}
                    title={"Accept a refactoring"}
                    description={
                        <p>
                            Let us help you! Sourcery's engine can automatically
                            make your Python code more idiomatic.{" "}
                            <HubLink
                                href={
                                    "https://docs.sourcery.ai/Tutorials/Introduction/#accepting-sourcerys-rules"
                                }
                                icon={"mi-book"}
                            >
                                Read the docs
                            </HubLink>
                        </p>
                    }
                />
                <GettingStartedItem
                    icon={"mi-clipboard-check"}
                    title={"Create a custom rule"}
                    description={
                        <p>
                            Extend Sourcery's built-in rules with your own.{" "}
                            <HubLink
                                icon={"mi-book"}
                                href={
                                    "https://docs.sourcery.ai/Tutorials/Custom-Rules/"
                                }
                            >
                                Read the tutorial
                            </HubLink>
                        </p>
                    }
                />
                <GettingStartedItem
                    icon={"mi-download"}
                    title={"Install the Sourcery CLI"}
                    description={
                        <p>
                            Install using <span className="font-mono">pip</span>{" "}
                            or use directly in your pre-commit config.{" "}
                            <HubLink
                                icon={"mi-book"}
                                href={
                                    "https://docs.sourcery.ai/Guides/Getting-Started/Command-Line/"
                                }
                            >
                                Installation instructions
                            </HubLink>
                        </p>
                    }
                />
                <GettingStartedItem
                    icon={"mi-window"}
                    title={"Review your code with the Sourcery CLI"}
                    description={
                        <p>
                            The CLI can be used to fix every issue in your code
                            base in a single command.{" "}
                            <Link
                                to={"/command-line"}
                                className={"text-orange-200"}
                            >
                                Read more<i className={"ml-3 mi-window"}></i>
                            </Link>
                        </p>
                    }
                />
                <GettingStartedItem
                    icon={"mi-folder-check"}
                    title={"Add Sourcery to your CI"}
                    description={
                        <p>
                            Get automatic checks on your pull requests and
                            merges.{" "}
                            <HubLink
                                href={
                                    "https://docs.sourcery.ai/Guides/Getting-Started/CI/"
                                }
                                icon={"mi-book"}
                            >
                                Read the guide
                            </HubLink>
                        </p>
                    }
                />
            </div>
        </div>
    );
};
