import React, { ReactElement, useState } from "react";
import { Link, RouteObject, useFetcher, useLoaderData } from "react-router-dom";
import { fetchJson } from "../api";
import * as _ from "lodash";
import { Switch } from "../components/Switch";
import { TextInput } from "../components/TextInput";
import { HubLink } from "../components/HubLink";
import classNames from "classnames";
import {
    Authenticated,
    AuthenticationData,
    isLoggedIn,
    NotAuthenticated,
} from "../Login";
import { ReactComponent as PythonLogo } from "../assets/language-icons/python-original.svg";
import { ReactComponent as JavaScriptLogo } from "../assets/language-icons/javascript-original.svg";
import { ReactComponent as TypeScriptLogo } from "../assets/language-icons/typescript-original.svg";

// Constants

const ruleGroups: RuleGroupData[] = [
    {
        ruleGroup: {
            title: "Default",
            name: "default",
            description:
                "Rules bundled with Sourcery which are enabled by default.",
            filterFunction: ({ rule }: RuleData) =>
                rule.tags.includes("default"),
        },
    },
];

const tagsToSkip = ["refactoring", "default"];

const languageIcons: Record<string, ReactElement> = {
    python: <PythonLogo style={{ height: "20px" }} title="Python" />,
    javascript: (
        <JavaScriptLogo style={{ height: "20px" }} title="JavaScript" />
    ),
    typescript: (
        <TypeScriptLogo style={{ height: "20px" }} title="TypeScript" />
    ),
};

// Interfaces

interface RuleData {
    rule: {
        id: string;
        kind: "refactoring" | "suggestion" | "comment" | "hover";
        languages: string[];
        tags: string[];
        description?: string;
    };
}

interface RuleGroupData {
    ruleGroup: {
        title: string;
        name: string;
        description: string;
        filterFunction: (rule: RuleData) => boolean;
    };
}

interface RulesData {
    rules: RuleData[];
}

interface ProjectConfigOk {
    version: string;
    ignore: string[];
    refactor: {
        include: string[];
        skip: string[];
        ruleTypes: ("refactoring" | "suggestion" | "comment")[];
        pythonVersion: {
            major: number;
            minor: number;
        };
    };
}

interface Position {
    line: number;
    column: number;
}

interface ProjectConfigError {
    errors: { message: string; location: { start: Position; end: Position } }[];
}

interface ProjectConfigData<T extends ProjectConfigOk | ProjectConfigError> {
    projectConfig: T;
}

// Functions

const isProjectConfigOk = (
    projectConfigData: ProjectConfigOk | ProjectConfigError
): projectConfigData is ProjectConfigOk =>
    !projectConfigData.hasOwnProperty("errors");

const isEnabled = (
    { rule }: RuleData,
    projectConfig: ProjectConfigOk,
    authenticated: Authenticated | NotAuthenticated
) => {
    return (
        !projectConfig.refactor.skip.includes(rule.id) &&
        !isFeatureLocked({ rule }, { authenticated })
    );
};

const isFeatureLocked = (
    { rule }: RuleData,
    { authenticated }: AuthenticationData<Authenticated | NotAuthenticated>
) => {
    return (
        rule.tags.includes("pro") &&
        (!isLoggedIn(authenticated) ||
            (authenticated.userClaims.product === "prod_opensource") || authenticated.userClaims.product === "prod_free")
    );
};

const ruleDocsLanguageName = ({ rule }: RuleData) => {
    if (rule.languages.includes("python")) {
        return "Python";
    } else if (rule.languages.includes("javascript")) {
        return "JavaScript";
    }
};

// Components

const RuleGroup = ({
    ruleGroup: { title, filterFunction, description },
    rules,
    searchTerm,
    projectConfig,
    authenticated,
}: {
    searchTerm: string;
    rules: RuleData[];
} & RuleGroupData &
    ProjectConfigData<ProjectConfigOk> &
    AuthenticationData<Authenticated | NotAuthenticated>) => {
    const [isToggledOpen, setIsToggledOpen] = useState(true);
    const isExpanded = isToggledOpen || searchTerm;
    const enabledRules = rules.filter((rule) =>
        isEnabled(rule, projectConfig, authenticated)
    );
    const filteredRules = _.uniqBy(rules, ({ rule }) => rule.id) // remove duplicates
        .filter(filterFunction) // get rule group rules
        .filter(({ rule }) => rule.id.includes(searchTerm)) // filter to search
        .sort(
            (
                { rule: ruleA },
                { rule: ruleB } // sort alphabetically
            ) => ruleA.id.localeCompare(ruleB.id)
        );

    return (
        <>
            <div
                className={
                    "flex flex-row justify-between items-center p-5 " +
                    "cursor-pointer border border-transparent border-b-black-200 bg-black-100 hover:border-black-200"
                }
                onClick={() => setIsToggledOpen(!isToggledOpen)}
            >
                <div className={"flex flex-col gap-3"}>
                    <div className="flex flex-row gap-4">
                        <span className={"font-bold"}>{title}</span>
                        {!searchTerm && (
                            <span className="text-black-300">
                                (click to {isExpanded ? "collapse" : "expand"})
                            </span>
                        )}
                    </div>
                    <p>
                        {enabledRules.length} of {rules.length} enabled
                    </p>
                    <p className={"text-black-300"}>{description}</p>
                </div>
                <i
                    className={classNames(
                        isExpanded ? "mi-chevron-up" : "mi-chevron-down",
                        searchTerm && "hidden",
                        "mr-4 text-xl"
                    )}
                ></i>
            </div>
            {isExpanded && (
                <ol
                    className={
                        "text-white flex flex-col ml-6 divide-y divide-black-100"
                    }
                >
                    {filteredRules.map(({ rule }) => {
                        return (
                            <li key={rule.id}>
                                <Rule
                                    rule={rule}
                                    projectConfig={projectConfig}
                                    authenticated={authenticated}
                                />
                            </li>
                        );
                    })}
                </ol>
            )}
        </>
    );
};

const Rule = ({
    rule,
    projectConfig,
    authenticated,
}: RuleData &
    ProjectConfigData<ProjectConfigOk> &
    AuthenticationData<Authenticated | NotAuthenticated>) => {
    const fetcher = useFetcher();
    const isFeatureLockedRule = isFeatureLocked({ rule }, { authenticated });
    const isDisabled = isFeatureLockedRule;
    const isChecked =
        isEnabled({ rule }, projectConfig, authenticated) && !isDisabled;

    const onChange = async () => {
        const newSkip = isChecked
            ? _.union(projectConfig.refactor.skip, [rule.id])
            : _.without(projectConfig.refactor.skip, rule.id);
        let formData = new FormData();
        formData.append("skip", JSON.stringify(newSkip));
        fetcher.submit(formData, {
            method: "put",
            action: "settings/update/skip",
        });
    };

    return (
        <div
            className={
                "flex flex-row justify-between hover:bg-gray-100 pt-5 pb-4 px-5"
            }
        >
            <div className="flex flex-col">
                <label
                    htmlFor={rule.id}
                    className={classNames(
                        "text-black-500 font-mono",
                        !isDisabled && "cursor-pointer"
                    )}
                >
                    <div className="flex flex-row items-center gap-5">
                        <span>{rule.id}</span>
                        {isFeatureLockedRule && (
                            <Link
                                to={"/account"}
                                className={
                                    "flex flex-row items-center gap-3 text-orange hover:text-orange-light"
                                }
                            >
                                <span
                                    className={"text-2xl"}
                                    title={"Upgrade to unlock"}
                                >
                                    <i className={"mi-lock"}></i>
                                </span>
                                <span className={"text-sm font-body"}>
                                    Upgrade?
                                </span>
                            </Link>
                        )}
                        <div className="flex flex-row items-center gap-3 mb-3">
                            {rule.languages.map((name) => languageIcons[name])}
                        </div>
                    </div>
                </label>
                <p className={"text-xs"}>
                    <HubLink
                        href={`https://docs.sourcery.ai/Reference/${ruleDocsLanguageName(
                            { rule }
                        )}/Default-Rules/${rule.id}/`}
                    >
                        View docs
                    </HubLink>
                </p>
                <div className={"mt-3 -ml-3"}>
                    {rule.tags
                        .filter((tag) => !tagsToSkip.includes(tag))
                        .map((tag) => (
                            <span
                                key={tag}
                                className="rounded-full bg-orange-100 text-black-500 font-body px-4 py-2 text-xs mr-3"
                            >
                                {tag}
                            </span>
                        ))}
                </div>
            </div>

            <Switch
                id={rule.id}
                checked={isChecked}
                onChange={onChange}
                disabled={isDisabled}
                title={isChecked ? "Toggle off" : "Toggle on"}
            />
        </div>
    );
};

// Views

export const Settings = () => {
    const { rules, projectConfig, authenticated } =
        useLoaderData() as RulesData &
            ProjectConfigData<ProjectConfigOk | ProjectConfigError> &
            AuthenticationData<Authenticated | NotAuthenticated>;

    return (
        <main
            className={
                "flex flex-col w-full h-screen overflow-y-scroll font-body text-black-500 py-8 px-9"
            }
        >
            {isProjectConfigOk(projectConfig) ? (
                <Rules
                    rules={rules}
                    projectConfig={projectConfig}
                    authenticated={authenticated}
                />
            ) : (
                <ConfigErrors projectConfig={projectConfig} />
            )}
        </main>
    );
};

const ConfigErrors = ({
    projectConfig,
}: ProjectConfigData<ProjectConfigError>) => {
    return (
        <div className="flex flex-col gap-5 bg-white max-w-[1024px] mx-auto font-body mt-5 rounded-sm p-7">
            <div className="flex flex-col">
                <h1 className={"font-body text-3xl font-bold"}>Config Error</h1>
                <div className="flex flex-row gap-5 mt-5">
                    <i className={"mi-warning"}></i>
                    <p>
                        Your project's{" "}
                        <span className="font-mono">.sourcery.yaml</span> file
                        is invalid. Please resolve the following errors:
                    </p>
                </div>
                <ol className={"mt-7 font-mono"}>
                    {projectConfig.errors.map(({ message, location }) => (
                        <li>
                            line {location.start.line}: {message}
                        </li>
                    ))}
                </ol>
            </div>
        </div>
    );
};

const Rules = ({
    rules,
    projectConfig,
    authenticated,
}: RulesData &
    ProjectConfigData<ProjectConfigOk> &
    AuthenticationData<Authenticated | NotAuthenticated>) => {
    const [searchTerm, setSearchTerm] = useState("");

    return (
        <>
            <h1 className="text-3xl">Rules</h1>

            <p
                className={
                    "text-black-300 mt-5 border-b-[2px] border-black-100 pb-5"
                }
            >
                Use this section to toggle rules on or off for your project.
                Note that these controls edit your project's{" "}
                <span className={"font-mono"}>.sourcery.yaml</span> file.
            </p>
            <TextInput
                inputProps={{
                    value: searchTerm,
                    onChange: ({ target: { value } }) => setSearchTerm(value),
                }}
                icon={searchTerm ? "mi-close cursor-pointer" : "mi-filter-alt"}
                iconProps={{
                    onClick: searchTerm ? () => setSearchTerm("") : undefined,
                }}
            />
            <ol className={"mt-6"}>
                {ruleGroups.map(({ ruleGroup }) => (
                    <li key={ruleGroup.name}>
                        <RuleGroup
                            ruleGroup={ruleGroup}
                            rules={rules}
                            searchTerm={searchTerm}
                            projectConfig={projectConfig}
                            authenticated={authenticated}
                        />
                    </li>
                ))}
            </ol>
        </>
    );
};

// Loaders and Actions

const fetchForSettings = async () => ({
    ...(await fetchJson<RulesData>("/sourcery/rules")),
    ...(await fetchJson<ProjectConfigOk | ProjectConfigError>(
        "/project/config/refactor/skip"
    )),
    ...(await fetchJson<AuthenticationData<Authenticated | NotAuthenticated>>(
        "/auth"
    )),
});

// Routes

export const routes: RouteObject[] = [
    {
        path: "settings",
        element: <Settings />,
        loader: fetchForSettings,
    },
    {
        path: "settings/update/skip",
        action: async ({ request }) =>
            fetch("/project/config/refactor/skip", {
                method: "PUT",
                body: await request.formData(),
            }),
    },
];
