import classNames from "classnames";
import React from "react";

interface BigIconInterface {
    icon: string;
    // rounded?: true | "full";
    // size?: "lg" | "xl" | "2xl" | "3xl";
    color?: string;
}

export const BigIcon = ({ icon, color }: BigIconInterface) => {
    return (
        <div
            className={classNames(
                `bg-${color ?? "black-200"}`,
                "w-[48px] h-[48px] flex flex-row justify-center items-center rounded-full"
            )}
        >
            <i className={classNames(icon, "text-2xl")}></i>
        </div>
    );
};
