import React from "react";

const openExternalLink = async (url: string) => {
    const component = encodeURIComponent(url);
    await fetch(`/utils/open-external-link?url=${component}`);
};

/**
 * This component is a slight hack to ensure links in VSCode can be used to open tabs in the browser.
 *
 * It's a shallow wrapper around the anchor element which dispatches the request to the backend, which
 * uses `click` to open the browser with the provided url.
 */
export const ExternalLink = ({
    href,
    children,
    ...props
}: React.AnchorHTMLAttributes<HTMLAnchorElement>) => {
    return (
        <a
            onClick={async (event) => {
                event.preventDefault();
                if (href) {
                    await openExternalLink(href);
                }
            }}
            href={href}
            {...props}
        >
            {children}
        </a>
    );
};
