import {
    Link,
    LoaderFunction,
    Navigate,
    redirect,
    RouteObject,
    useFetcher,
    useLoaderData,
    useRouteError,
} from "react-router-dom";
import React, { useEffect } from "react";
import { fetchJson, isErrorResponse } from "./api";
import { ActionFunction } from "react-router";
import "mono-icons/iconfont/icons.css";
import "./App.css";
import { Spinner } from "./components/Spinner";
import { BigIcon } from "./components/BigIcon";

// Interfaces

export interface AuthenticationData<
    T extends Authenticated | NotAuthenticated
> {
    authenticated: T;
}

interface VerificationData {
    deviceCode: string;
    userCode: string;
    verificationUri: string;
    expiresIn: number;
    interval: number;
    verificationUriComplete: string;
}

export interface Authenticated {
    isAuthenticated: true;
    userClaims: {
        product: "prod_opensource" | "prod_free" | "prod_pro" | "prod_teammember" | "prod_team" | null;
        productName: string | null;
        featureFlags: string[];
        userMessage: string | null;
        userMessageUrl: string | null;
        hasToken: boolean;
        hasNoConnection: boolean;
    };
}

export interface NotAuthenticated {
    isAuthenticated: false;
}

// Functions

export const isAuthenticated = (
    authenticated: Authenticated | NotAuthenticated | undefined
): authenticated is Authenticated => {
    if (!authenticated) {
        return false;
    }
    return authenticated.isAuthenticated;
};

export const isLoggedIn = (
    authenticated: Authenticated | NotAuthenticated
): authenticated is Authenticated => {
    return (
        isAuthenticated(authenticated) && authenticated.userClaims.hasToken
    );
};

// Views

export const LoginVerification = () => {
    // Display user code and redirect to login confirmation
    const fetcher = useFetcher();
    const loginVerification = useLoaderData() as VerificationData;

    useEffect(() => {
        const formData = new FormData();
        Object.entries(loginVerification).forEach(([key, value]) =>
            formData.append(key, value)
        );

        setTimeout(
            () =>
                fetcher.submit(formData, {
                    method: "post",
                    action: "/login/confirmation",
                }),
            2000
        );
        // see discussion about dependencies and eslint issues here:
        // https://stackoverflow.com/questions/53120972/how-to-call-loading-function-with-react-useeffect-only-once/
        // disabling the check for now as this style of load "on mount" is a well-recognized pattern, but
        // this entire routine should be extracted into a function at some point to allow the effect to have
        // correct dependencies
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    return (
        <main
            className={
                "flex flex-col py-7 mx-auto w-full h-screen bg-black-500 justify-center items-center BackgroundImage"
            }
        >
            <div className="bg-white p-8 rounded w-[448px] text-black-500 font-body">
                <h1 className="text-3xl">Signing you in...</h1>
                <p className={"mt-5 text-black-300"}>
                    We've opened a tab in your browser.
                </p>
                <p className={"mt-5 text-black-300"}>
                    Follow the authentication steps, and check back here when
                    you're done!
                </p>

                <h2 className="mt-7 font-bold">Verification code</h2>
                <p
                    className={
                        "font-mono mt-4 bg-gray-100 p-4 rounded-sm border-b-2 border-black-200"
                    }
                >
                    {loginVerification.userCode}
                </p>

                <p className="mt-7 font-mono text-xs">
                    Awaiting response from authentication server...
                </p>

                <div className="mt-7 flex flex-col items-center">
                    <Spinner />
                </div>
            </div>
        </main>
    );
};

export const LoginConfirmation = () => {
    const { authenticated } =
        useLoaderData() as AuthenticationData<Authenticated>;

    return (
        <main
            className={
                "flex flex-col py-7 mx-auto w-full h-screen bg-black-500 justify-center items-center BackgroundImage"
            }
        >
            <div className="bg-white p-8 rounded w-[448px] text-black-500 font-body">
                <BigIcon icon={"mi-check"} color={"orange-100"} />
                <h1 className="text-3xl mt-5">Success!</h1>
                <p className={"mt-5 text-black-300"}>
                    You're signed in on your{" "}
                    {authenticated.userClaims.productName} plan.
                </p>
                <Link
                    to={"/"}
                    className={
                        "bg-orange-200 font-bold mt-7 flex flex-row justify-between items-center p-5 rounded-sm hover:bg-opacity-90"
                    }
                >
                    <span>View dashboard</span>
                    <i className="ml-5 mi-arrow-right"></i>
                </Link>
            </div>
        </main>
    );
};

export const LoginFailure = () => {
    // Failure to log in - not an application error
    const error = useRouteError() as any;
    const errorMessage = isErrorResponse(error)
        ? `${error.code} ${error.name}: ${error.description}`
        : error.toString();

    return (
        <main
            className={
                "flex flex-col py-7 mx-auto w-full h-screen bg-black-500 justify-center items-center BackgroundImage"
            }
        >
            <div className="bg-white p-8 rounded w-[448px] text-black-500 font-body">
                <BigIcon icon={"mi-close"} />
                <h1 className="text-3xl mt-5">Failed to Sign In</h1>
                <p className={"font-mono mt-5"}>{errorMessage}</p>
                <p className="font-body text-black-300 mt-7">
                    We were unable to sign in your device.
                </p>
                <p className="font-body text-black-300 mt-5">
                    Please try again, and if the issue persists, please contact
                    us at{" "}
                    <a
                        href="mailto:hello@sourcery.ai"
                        className={"text-orange-200"}
                    >
                        hello@sourcery.ai
                    </a>
                </p>
                <Link
                    to={"/"}
                    className={
                        "bg-orange-200 font-bold mt-7 flex flex-row justify-between items-center p-5 rounded-sm hover:bg-opacity-90"
                    }
                >
                    <span>View dashboard</span>
                    <i className="ml-5 mi-arrow-right"></i>
                </Link>
            </div>
        </main>
    );
};

// Components

interface LoginButtonProps {
    authenticated: Authenticated | NotAuthenticated;
}

export const LoginButton = ({ authenticated }: LoginButtonProps) => {
    if (!isAuthenticated(authenticated)) {
        // User is not authenticated
        return (
            <Link
                to={"/login/verification"}
                className={"py-5 hover:text-gray-light"}
            >
                Sign In
                <i className="ml-5 mi-log-in"></i>
            </Link>
        );
    }
    if (!isLoggedIn(authenticated)) {
        // User is authenticated, but not logged in (no token)
        return (
            <Link
                to={"/login/verification"}
                className={"py-5 hover:text-gray-light"}
            >
                Sign In
                <i className="ml-5 mi-log-in"></i>
            </Link>
        );
    }
    // User is logged in
    return (
        <p className={"py-5"}>
            {authenticated.userClaims.productName
                ? authenticated.userClaims.productName + " Plan"
                : "Signed In"}
        </p>
    );
};

// Loaders and Actions
export const authentication = (
    redirectOnAuthenticated?: string,
    redirectOnUnAuthenticated?: string
) => {
    const authentication: LoaderFunction = async () => {
        // Read authentication
        const authenticationData = await fetchJson<
            AuthenticationData<Authenticated | NotAuthenticated>
        >("/auth");
        if (
            !isAuthenticated(authenticationData.authenticated) &&
            redirectOnUnAuthenticated
        ) {
            return redirect(redirectOnUnAuthenticated);
        }
        if (
            isAuthenticated(authenticationData.authenticated) &&
            redirectOnAuthenticated
        ) {
            return redirect(redirectOnAuthenticated);
        }
        return authenticationData;
    };
    return authentication;
};

const verification: LoaderFunction = async () => {
    // Get verification code
    return await fetchJson<VerificationData>("/auth/login-verification");
};

const confirmation: ActionFunction = async ({ request }) => {
    // Get login confirmation
    const verification = Object.fromEntries(await request.formData());
    await fetchJson<AuthenticationData<Authenticated>>(
        "/auth/login-confirmation",
        {
            method: "POST",
            body: JSON.stringify(verification),
            headers: { "Content-Type": "application/json" },
        }
    );
    return redirect("/login/confirmation");
};

// Routes

export const routes: RouteObject[] = [
    {
        path: "login",
        element: <Navigate to={"/login/verification"} />,
    },
    {
        path: "login/verification",
        element: <LoginVerification />,
        errorElement: <LoginFailure />,
        loader: verification,
    },
    {
        path: "login/confirmation",
        element: <LoginConfirmation />,
        action: confirmation,
        loader: authentication(),
        errorElement: <LoginFailure />,
    },
];
