import {
    Link,
    LoaderFunction,
    Navigate,
    NavLink,
    NavLinkProps,
    Outlet,
    RouteObject,
    useLoaderData,
    useRouteError,
} from "react-router-dom";
import {
    Authenticated,
    authentication,
    AuthenticationData,
    NotAuthenticated,
} from "./Login";
import { routes as settingsRoutes } from "./pages/Settings";
import { ReactComponent as SourceryLogo } from "./assets/sourcery-logo.svg";
import React, { ReactNode } from "react";
import "./App.css";
import "mono-icons/iconfont/icons.css";
import { fetchJson, isErrorResponse, isStatusResponse } from "./api";
import { GettingStarted } from "./pages/GettingStarted";
import classNames from "classnames";
import { CommandLine } from "./pages/CommandLine";
import { Account } from "./pages/Account";
import { PlanPill } from "./components/PlanPill";

// Interfaces

interface ContextData {
    context: {
        projectPath: string;
    };
}

// Components

interface HubNavLinkProps {
    title: ReactNode;
    icon: string;
    to: NavLinkProps["to"];
}

const HubNavLink = ({ title, icon, to }: HubNavLinkProps) => (
    <NavLink
        to={to}
        className={({ isActive }) =>
            classNames(
                "py-5 px-6 hover:text-white rounded-sm",
                isActive && "bg-black-300 text-white hover:text-black-200"
            )
        }
    >
        <div className="flex flex-row gap-4 items-center">
            <span className={"text-2xl"}>
                <i className={icon}></i>
            </span>
            <div className={"flex flex-grow"}>{title}</div>
        </div>
    </NavLink>
);

// Views

export const Root = () => {
    const { authenticated, context } = useLoaderData() as AuthenticationData<
        Authenticated | NotAuthenticated
    > & ContextData;

    return (
        <div className={"flex flex-row w-full h-screen"}>
            <header className="flex flex-col py-7 px-3 gap-4 min-w-[256px] bg-black-500 font-body font-bold text-black-200">
                <Link to={"/"} className={"px-6"}><SourceryLogo className={"h-[40px] mb-7"}/></Link>
                <HubNavLink
                    to={"getting-started"}
                    title={"Getting started"}
                    icon={"mi-circle-check"}
                />
                <HubNavLink
                    to={"settings"}
                    title={"Project config"}
                    icon={"mi-clipboard-check"}
                />
                <HubNavLink
                    to={"command-line"}
                    title={"Command Line"}
                    icon={"mi-window"}
                />
                <HubNavLink
                    to={"account"}
                    title={
                        <div className="flex flex-row flex-grow justify-between items-center">
                            <span>Your Plan</span>
                            <PlanPill authenticated={authenticated} />
                        </div>
                    }
                    icon={"mi-user"}
                />
            </header>
            <div className="flex flex-col w-full">
                <Outlet />
                <div className="flex flex-row py-3 px-4 bg-black-100 text-sm border-t border-black-200">Active project: {context.projectPath}</div>
            </div>
        </div>
    );
};

export const RootError = () => {
    const error = useRouteError() as any;
    const errorMessage = isErrorResponse(error)
        ? `${error.code} ${error.name}: ${error.description}`
        : isStatusResponse(error)
        ? `${error.status} ${error.statusText}`
        : error.toString();

    return (
        <div className={"flex flex-col w-full justify-center"}>
            <main className="flex flex-col py-7 mx-auto w-full max-w-[1024px]">
                <h1 className="font-bold font-body text-3xl">Error</h1>
                <p className="font-mono mt-5">{errorMessage}</p>
                <p className="font-body mt-7">
                    If this problem persists, please contact us at{" "}
                    <a
                        href="mailto:support@sourcery.ai"
                        className={"text-orange-200"}
                    >
                        support@sourcery.ai
                    </a>
                </p>
            </main>
        </div>
    );
};

// Loaders and Actions

const fetchForRoot: LoaderFunction = async () => {
    return {
        ...(await fetchJson<
            AuthenticationData<Authenticated | NotAuthenticated>
        >("/auth")),
        ...(await fetchJson<ContextData>("/context")),
    };
};

// Routes

export const routes: RouteObject[] = [
    {
        path: "/",
        element: <Root />,
        errorElement: <RootError />,
        loader: fetchForRoot,
        children: [
            {
                index: true,
                element: <Navigate to={"/getting-started"} />,
            },
            {
                path: "getting-started",
                element: <GettingStarted />,
                loader: async () => await fetchJson<AuthenticationData<Authenticated | NotAuthenticated>>("/auth"),
            },
            {
                path: "command-line",
                element: <CommandLine />,
            },
            {
                path: "account",
                element: <Account />,
                loader: authentication(),
            },
            ...settingsRoutes,
        ],
    },
];
