import React from "react";
import { HubLink } from "../components/HubLink";

// Views

interface CommandLineProps {
    subCommand: string;
    description: React.ReactNode;
}

const CommandLineCheat = ({ subCommand, description }: CommandLineProps) => (
    <div className="border-t border-black-100 pt-7 pb-6">
        <code className="font-mono px-5 py-4 bg-black-400 text-white rounded-sm">
            <span className={"text-black-200"}>sourcery</span> {subCommand}
        </code>
        <p className="text-black-300 mt-5">{description}</p>
    </div>
);

export const CommandLine = () => {
    return (
        <div
            className={
                "flex flex-col flex-grow h-screen overflow-y-scroll font-body text-black-500 py-8 px-9"
            }
        >
            <h1 className="text-3xl mb-5">Command Line</h1>
            <p className="text-black-300 mb-5">
                Sourcery works great on the command line. Try out some of the
                commands below, or{" "}
                <HubLink
                    href={
                        "https://docs.sourcery.ai/Guides/Getting-Started/Command-Line/"
                    }
                >
                    read the docs online.
                </HubLink>
            </p>
            <main className="flex flex-col">
                <div className="py-7 border-t-[2px] border-black-100">
                    <h2 className="font-bold">Setup</h2>
                    <p className={"text-black-300 mt-3 mb-6"}>
                        Use these commands after you've installed Sourcery to
                        get set up quickly.
                    </p>
                    <CommandLineCheat
                        subCommand={"login"}
                        description={
                            "Opens a browser window to authenticate your device."
                        }
                    />
                    <CommandLineCheat
                        subCommand={"init config"}
                        description={
                            <>
                                Create a default{" "}
                                <span className="font-mono">
                                    .sourcery.yaml
                                </span>{" "}
                                configuration file in the current directory.
                            </>
                        }
                    />
                    <CommandLineCheat
                        subCommand={"init pre-commit"}
                        description={
                            <>
                                Create or update{" "}
                                <span className="font-mono">
                                    .pre-commit-config.yaml
                                </span>{" "}
                                to use Sourcery.
                            </>
                        }
                    />
                    <CommandLineCheat
                        subCommand={"init ci"}
                        description={"View instructions to add Sourcery to your CI."}
                    />
                    <CommandLineCheat
                        subCommand={"--help"}
                        description={
                            "See all available commands and see full specification."
                        }
                    />
                </div>
                <div className="py-7 border-t-[2px] border-black-100">
                    <h2 className="font-bold">Review and Refactor</h2>
                    <p className="text-black-300 mt-3 mb-6">
                        Use these commands to scan your code for issues and
                        automatically fix them where possible.
                    </p>
                    <CommandLineCheat
                        subCommand={"review ."}
                        description={
                            "Find issues in all files in the current directory."
                        }
                    />
                    <CommandLineCheat
                        subCommand={"review --fix ."}
                        description={
                            "Automatically find and fix issues in files in the\n" +
                            "                            current directory."
                        }
                    />
                    <CommandLineCheat
                        subCommand={'review --diff "git diff" .'}
                        description={
                            <>
                                Find issues in code which has changed according
                                to the <span className="font-mono">diff</span>{" "}
                                command.
                            </>
                        }
                    />
                </div>
            </main>
        </div>
    );
};
