import { Authenticated, AuthenticationData, NotAuthenticated } from "../Login";
import classNames from "classnames";
import React from "react";

export const PlanPill = ({
    authenticated,
}: AuthenticationData<Authenticated | NotAuthenticated>) => (
    <>
        {authenticated.isAuthenticated && (
            <span
                className={classNames(
                    "text-sm rounded-full px-4 py-3 text-black-500",
                    authenticated.userClaims.product === "prod_free"
                        ? "bg-black-100"
                        : authenticated.userClaims.product === "prod_pro"
                        ? "bg-orange-200"
                        : "bg-purple-200"
                )}
            >
                {authenticated.userClaims.productName}
            </span>
        )}
    </>
);
