import React, {InputHTMLAttributes} from "react";
import classNames from "classnames";

export const Switch = (props: InputHTMLAttributes<HTMLInputElement>) => {
    return (
        <label className={"relative inline-block w-[40px] h-[24px]"}>
            <input
                type={"checkbox"}
                className={classNames("peer opacity-0 w-0 h-0")}
                {...props}
            />
            <span
                className={classNames(
                    "absolute cursor-pointer top-0 left-0 right-0 bottom-0 bg-black-100 border-solid border border-black-200 transition-transform duration-300 rounded-[24px] " +
                    "before:absolute before:h-[16px] before:w-[16px] before:left-[4px] before:top-[3px] before:bg-black-300 transition-transform before:duration-300 before:rounded-[50%] " +
                    "peer-checked:before:translate-x-[14px] peer-checked:bg-orange-200 peer-checked:before:bg-black-500 " +
                    "hover:border-black-300", props.disabled && "cursor-not-allowed bg-black-200")
                }
                title={props.title}
            ></span>
        </label>
    );
};
