export const fetchJson = async <T>(
    url: string,
    init?: RequestInit
): Promise<T> => {
    return fetch(url, init).then(handleJsonResponse);
};

const handleJsonResponse = async (response: Response) => {
    if (response.ok) {
        return await response.json();
    } else {
        throw await response.json(); // we convert all backend errors to json
    }
};

interface ErrorResponse {
    code: number;
    name: string;
    description: string;
}

interface StatusResponse {
    status: number;
    statusText: string;
    data: any;
}

export const isErrorResponse = (error: any): error is ErrorResponse => {
    return (
        error.hasOwnProperty("code") &&
        error.hasOwnProperty("name") &&
        error.hasOwnProperty("description")
    );
};

export const isStatusResponse = (error: any): error is StatusResponse => {
    return (
        error.hasOwnProperty("status") &&
        error.hasOwnProperty("statusText")
    );
};
